/**
 * Shared authentication flow utility
 * Used by both login and init commands
 */
export interface AuthFlowOptions {
    /** Whether to open browser automatically */
    openBrowser?: boolean;
    /** Whether to show success message */
    showSuccessMessage?: boolean;
    /**
     * Invoked once the auth session exists, BEFORE polling starts. Lets a caller
     * surface the authorization URL/code immediately (e.g. as JSON) instead of
     * silently waiting up to the poll timeout.
     */
    onSessionCreated?: (session: {
        authUrl: string;
        sessionCode: string;
        expiresAt: string;
    }) => void;
}
/** Bounded stage the auth flow reached when it failed. */
export type AuthFailureStage = 'preflight' | 'create_session' | 'open_browser' | 'poll' | 'claim' | 'save_config';
/** Bounded, privacy-safe classification of an auth failure. */
export type AuthFailureCode = 'config_error' | 'connection_error' | 'api_error' | 'timeout' | 'authorization_denied' | 'unknown';
export interface AuthFlowSuccess {
    success: true;
    teamId?: string;
    teamName?: string;
    apiKey?: string;
    userId?: string;
}
export interface AuthFlowFailure {
    success: false;
    /** Stage the flow reached before failing. */
    stage: AuthFailureStage;
    /** Bounded failure classification. */
    code: AuthFailureCode;
    /** Human-readable message (rendered once by the caller). */
    error: string;
}
export type AuthFlowResult = AuthFlowSuccess | AuthFlowFailure;
/**
 * Run the device authentication flow
 * Creates a session, opens browser for authorization, polls for approval, and saves credentials
 */
export declare function runAuthFlow(options?: AuthFlowOptions): Promise<AuthFlowResult>;
